def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Return True if any two distinct numbers in `numbers` are closer to each other
    than `threshold`. If the list has fewer than two elements, or the threshold
    is non‑positive, the function returns False.
    """
    # Basic argument validation
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("`numbers` must be a list or tuple of floats")
    if not isinstance(threshold, (int, float)):
        raise TypeError("`threshold` must be an int or float")

    # Non‑positive threshold can never be satisfied
    if threshold <= 0:
        return False

    # Need at least two numbers to compare
    if len(numbers) < 2:
        return False

    # Ensure all elements are numeric
    try:
        sorted_numbers = sorted(numbers)
    except Exception as exc:
        raise TypeError("All items in `numbers` must be convertible to float") from exc

    # Check neighbouring pairs in the sorted list
    for i in range(len(sorted_numbers) - 1):
        if (sorted_numbers[i + 1] - sorted_numbers[i]) < threshold:
            return True

    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of numbers.")
    n = len(numbers)
    if n == 0:
        raise ValueError("Mean absolute deviation is undefined for an empty list.")
    try:
        mean_value = sum(numbers) / n
    except Exception as exc:
        raise TypeError("All elements in the list must be numeric.") from exc
    abs_diff_sum = 0.0
    for x in numbers:
        abs_diff_sum += abs(x - mean_value)
    return abs_diff_sum / n

def add(a: int, b: int) -> int:
    """Adds two integer numbers together."""
    if not isinstance(a, int):
        raise TypeError(f"First argument must be an int, got {type(a).__name__}")
    if not isinstance(b, int):
        raise TypeError(f"Second argument must be an int, got {type(b).__name__}")
    try:
        return a + b
    except Exception as exc:
        raise ArithmeticError(f"Error adding {a} and {b}: {exc}") from exc

def calculate_scholarship(grades: list[int], leader: str, west: str, papers: int) -> int:
    """Calculate the scholarship amount based on academic performance and other criteria.

    Parameters:
    grades (list[int]): [end_of_term_average, class_evaluation]
    leader (str): 'Y' or 'N' indicating if the student is a class leader
    west (str): 'Y' or 'N' indicating if the student is from a western province
    papers (int): Number of research papers published

    Returns:
    int: Total scholarship amount

    Raises:
    ValueError: If inputs are of incorrect type or outside expected values
    """
    # Validate grades
    if not isinstance(grades, list):
        raise ValueError("grades must be a list")
    if len(grades) != 2:
        raise ValueError("grades must contain exactly two elements")
    try:
        avg, eval_score = float(grades[0]), float(grades[1])
    except (ValueError, TypeError):
        raise ValueError("grades must contain numeric values")

    # Validate leader and west
    if not isinstance(leader, str) or leader not in {"Y", "N"}:
        raise ValueError("leader must be 'Y' or 'N'")
    if not isinstance(west, str) or west not in {"Y", "N"}:
        raise ValueError("west must be 'Y' or 'N'")

    # Validate papers
    if not isinstance(papers, int) or papers < 0:
        raise ValueError("papers must be a non‑negative integer")

    scholarship = 0

    # 1. Scholarship based on papers and average
    if avg > 80 and papers >= 1:
        scholarship += 8000

    # 2. Additional increments
    if avg > 85 and eval_score > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == "Y":
        scholarship += 1000
    if eval_score > 80 and leader == "Y":
        scholarship += 850

    return scholarship

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters:
        encoded (str): The encoded string representing the mapping source.
        original (str): The original string corresponding to the encoded string.
        message (str): The message to decode.

    Returns:
        str: The decoded message or "Failed" if decoding cannot be performed.
    """
    # Quick sanity check on lengths
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    used_values = set()

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            if orig_char in used_values:
                # Two encoded chars map to the same original: not bijective
                return "Failed"
            mapping[enc_char] = orig_char
            used_values.add(orig_char)

    # The cipher is assumed to be a full substitution of the 26 letters
    if len(mapping) != 26 or len(used_values) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.
    """
    import sys
    from functools import lru_cache

    # Basic validation
    if not all(isinstance(v, int) for v in (n, k, x)):
        raise TypeError("All arguments must be integers")
    if k <= 0 or x <= 0 or n < 0:
        return 0
    if n < k * x:
        return 0

    # Recursion depth may need to be increased for large k
    sys.setrecursionlimit(max(1000, k * 10))

    @lru_cache(None)
    def helper(remaining_sum: int, remaining_parts: int, min_val: int) -> int:
        # Base cases
        if remaining_parts == 0:
            return 1 if remaining_sum == 0 else 0
        if remaining_sum < remaining_parts * min_val:
            return 0

        total = 0
        # The first part v must be at least min_val and at most remaining_sum // remaining_parts
        max_v = remaining_sum // remaining_parts
        for v in range(min_val, max_v + 1):
            total += helper(remaining_sum - v, remaining_parts - 1, v)
        return total

    return helper(n, k, x)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
        x0 (int): The GCD that each pair (P, Q) must have.
        y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
        int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    # Validate inputs
    if not isinstance(x0, int) or not isinstance(y0, int):
        raise TypeError("x0 and y0 must be integers")
    if x0 <= 0 or y0 <= 0:
        return 0
    if x0 > y0:
        return 0
    if y0 % x0 != 0:
        return 0

    # Helper: Euclidean algorithm for GCD
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    k = y0 // x0
    count = 0
    import math  # local import to avoid global namespace clutter
    for a in range(1, int(k**0.5) + 1):
        if k % a == 0:
            b = k // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
                                as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    # Basic input validation
    try:
        if not isinstance(n, int):
            raise ValueError("n must be an integer")
        if not isinstance(rules, list):
            raise ValueError("rules must be a list of tuples")
        # Build mapping from source digit to list of destination digits
        digit_map = {}
        for rule in rules:
            if (
                not isinstance(rule, tuple)
                or len(rule) != 2
                or not isinstance(rule[0], int)
                or not isinstance(rule[1], int)
            ):
                raise ValueError("Each rule must be a tuple of two integers")
            src, dst = rule
            if src < 0 or src > 9 or dst < 0 or dst > 9:
                raise ValueError("Rule digits must be between 0 and 9 inclusive")
            digit_map.setdefault(src, []).append(dst)
    except Exception:
        # On invalid input or other errors, return 0 to indicate failure
        return 0

    start = str(abs(n))  # Use absolute value to avoid negative sign in transformations
    visited = {start}
    queue = [start]

    while queue:
        current = queue.pop(0)
        current_digits = list(current)
        for idx, ch in enumerate(current_digits):
            src_digit = int(ch)
            if src_digit in digit_map:
                for dst_digit in digit_map[src_digit]:
                    new_digits = current_digits.copy()
                    new_digits[idx] = str(dst_digit)
                    new_num_str = "".join(new_digits)
                    if new_num_str not in visited:
                        visited.add(new_num_str)
                        queue.append(new_num_str)

    return len(visited)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Validate time limit
    if T <= 0:
        return 0
    # Adjust M if it does not match the actual number of herbs
    M = min(M, len(herbs))
    # Prepare DP array for 0/1 knapsack
    dp = [0] * (T + 1)
    for i in range(M):
        time, value = herbs[i]
        # Skip items with non-positive time or negative time
        if time <= 0 or value <= 0:
            continue
        if time > T:
            continue
        # Update dp array backwards to maintain 0/1 property
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return max(dp) if dp else 0

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    # basic validation
    if not isinstance(n, int) or not isinstance(m, int):
        raise ValueError("n and m must be integers")
    if n < 0 or m < 0:
        raise ValueError("n and m must be non‑negative")
    if not isinstance(a, list) or len(a) != n:
        raise ValueError("a must be a list of length n")
    for limit in a:
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("All limits in a must be non‑negative integers")

    total_capacity = sum(a)
    if m > total_capacity:
        return 0

    # DP: dp[k] = number of ways to fill k pots with processed types
    dp = [0] * (m + 1)
    dp[0] = 1

    for limit in a:
        # prefix sums of dp for efficient range sum queries
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD

        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            l = k - limit
            if l <= 0:
                new_dp[k] = prefix[k]  # sum dp[0..k]
            else:
                new_dp[k] = (prefix[k] - prefix[l - 1]) % MOD
        dp = new_dp

    return dp[m] % MOD
